/**
 * STYLE JIG MULTI-DONOR VARIANT NOTCHES RUNTIME (`variant-notches.js`)
 * Standalone right-side vertically centered donor variant selector (`1/N .. N/N`).
 *
 * Reads multi-donor image lists per style slot from:
 *   1. `window.__STYLE_VARIANTS__` (custom mapping `{ [slot]: [{ label, file, ... }] }`)
 *   2. `window.__SKILL_FOLDER_MANIFEST__` (manifest generated by `init_style_jig.py` / `match_and_map_styles.py`)
 *   3. Built-in default 5-slot registry
 *
 * Dispatches:
 *   - `document.body.setAttribute('data-style-variant', String(idx))`
 *   - `window.dispatchEvent(new CustomEvent('jig-style-variant', { detail: { style, variant, label, file } }))`
 *   - `iframe.contentWindow.postMessage({ type: 'SET_STYLE_VARIANT', style, variant, label, file }, '*')`
 */
(function initJigVariantNotches(global) {
  'use strict';

  var DEFAULT_STYLE_VARIANTS = {
    brutal: [
      { label: 'Variant 01 · Brutal Volt', file: '01-brutal.jpg' },
      { label: 'Variant 02 · Brutal Frame', file: '02-brutal.jpg' },
      { label: 'Variant 03 · Brutal Zine', file: '03-brutal.jpg' },
      { label: 'Variant 04 · Brutal Poster', file: '04-brutal.jpg' },
      { label: 'Variant 05 · Brutal Stencil', file: '05-brutal.jpg' }
    ],
    clean: [
      { label: 'Variant 01 · Clean Squircle', file: '01-clean.jpg' },
      { label: 'Variant 02 · Clean Bento', file: '02-clean.jpg' },
      { label: 'Variant 03 · Clean Tactile', file: '03-clean.jpg' },
      { label: 'Variant 04 · Clean Inspector', file: '04-clean.jpg' },
      { label: 'Variant 05 · Clean Radial', file: '05-clean.png' }
    ],
    grid: [
      { label: 'Variant 01 · Grid Blueprint', file: '01-grid.jpg' },
      { label: 'Variant 02 · Grid Halftone', file: '02-grid.jpg' },
      { label: 'Variant 03 · Grid Axonometric', file: '03-grid.jpg' },
      { label: 'Variant 04 · Grid Tangent', file: '04-grid.jpg' },
      { label: 'Variant 05 · Grid Matrix', file: '05-grid.jpg' }
    ],
    editorial: [
      { label: 'Variant 01 · Editorial Monograph', file: '01-editorial.jpg' },
      { label: 'Variant 02 · Editorial Risograph', file: '02-editorial.jpg' },
      { label: 'Variant 03 · Editorial Spread', file: '03-editorial.jpg' },
      { label: 'Variant 04 · Editorial Broadsheet', file: '04-editorial.jpg' },
      { label: 'Variant 05 · Editorial Index', file: '05-editorial.jpg' }
    ],
    cinematic: [
      { label: 'Variant 01 · Cinematic HUD', file: '01-cinematic.jpg' },
      { label: 'Variant 02 · Cinematic Bokeh', file: '02-cinematic.jpg' },
      { label: 'Variant 03 · Cinematic Digiplate', file: '03-cinematic.jpg' },
      { label: 'Variant 04 · Cinematic Chrome', file: '04-cinematic.jpg' },
      { label: 'Variant 05 · Cinematic Stage', file: '05-cinematic.jpg' }
    ],
    product: [
      { label: 'Variant 01 · Product Bento', file: '01-product.jpg' },
      { label: 'Variant 02 · Product Plush', file: '02-product.jpg' },
      { label: 'Variant 03 · Product Network', file: '03-product.jpg' },
      { label: 'Variant 04 · Product Telemetry', file: '04-product.png' }
    ],
    playful: [
      { label: 'Variant 01 · Playful Telop', file: '01-playful.jpg' },
      { label: 'Variant 02 · Playful Voxel', file: '02-playful.jpg' },
      { label: 'Variant 03 · Playful Pop Bento', file: '03-playful.jpg' },
      { label: 'Variant 04 · Playful Sticker', file: '04-playful.jpg' },
      { label: 'Variant 05 · Playful Meadow', file: '05-playful.jpg' }
    ],
    retro: [
      { label: 'Variant 01 · Retro Desktop', file: '01-retro.jpg' },
      { label: 'Variant 02 · Retro CRT Vector', file: '02-retro.jpg' },
      { label: 'Variant 03 · Retro 8-Bit Pixel', file: '03-retro.jpg' },
      { label: 'Variant 04 · Retro Messenger', file: '04-retro.png' },
      { label: 'Variant 05 · Retro Audio Rack', file: '05-retro.jpg' }
    ]
  };

  function resolveVariantsMap() {
    if (global.__STYLE_VARIANTS__ && typeof global.__STYLE_VARIANTS__ === 'object') {
      return global.__STYLE_VARIANTS__;
    }
    if (global.__SKILL_FOLDER_MANIFEST__ && typeof global.__SKILL_FOLDER_MANIFEST__ === 'object') {
      var out = {};
      Object.keys(global.__SKILL_FOLDER_MANIFEST__).forEach(function (slot) {
        var entry = global.__SKILL_FOLDER_MANIFEST__[slot];
        var imgs = (entry && (entry.images || entry.donor_images)) || [];
        if (imgs.length > 0) {
          out[slot] = imgs.map(function (fname, i) {
            return {
              label: slot + ' · ' + (i + 1) + '/' + imgs.length,
              file: fname
            };
          });
        }
      });
      if (Object.keys(out).length > 0) return out;
    }
    return DEFAULT_STYLE_VARIANTS;
  }

  function mountVariantNotches() {
    if (typeof document === 'undefined' || !document.body) return null;

    var nav = document.querySelector('.right-variant-notches');
    if (!nav) {
      nav = document.createElement('nav');
      nav.id = 'jigStyleVariants';
      nav.className = 'right-variant-notches is-hidden';
      nav.setAttribute('aria-label', 'Style donor variants');

      var track = document.createElement('div');
      track.className = 'rvn-track';
      nav.appendChild(track);

      var tooltip = document.createElement('div');
      tooltip.className = 'rvn-tooltip';
      tooltip.setAttribute('role', 'status');
      tooltip.setAttribute('aria-live', 'polite');

      var tooltipImg = document.createElement('img');
      tooltipImg.className = 'rvn-tooltip-img';
      tooltipImg.alt = '';
      tooltipImg.draggable = false;
      tooltip.appendChild(tooltipImg);

      var tooltipLbl = document.createElement('div');
      tooltipLbl.className = 'rvn-tooltip-label';
      tooltip.appendChild(tooltipLbl);

      nav.appendChild(tooltip);
      document.body.appendChild(nav);
    }

    var trackEl = nav.querySelector('.rvn-track');
    var tooltipEl = nav.querySelector('.rvn-tooltip');
    var tooltipImgEl = nav.querySelector('.rvn-tooltip-img');
    var tooltipLblEl = nav.querySelector('.rvn-tooltip-label');

    var activeStyle = getBodyStyle();
    var activeVariant = 0;
    var renderedStyle = '';

    function getBodyStyle() {
      return (
        document.body.getAttribute('data-jig') ||
        document.body.getAttribute('data-style') ||
        document.documentElement.getAttribute('data-style') ||
        'clone'
      );
    }

    function getVariantsForStyle(style) {
      var map = resolveVariantsMap();
      return map[style] || [];
    }

    function resolveThumbSrc(style, file) {
      var thumbs = global.__STYLE_VARIANT_THUMBS__;
      if (thumbs) {
        if (thumbs[style + '/' + file]) return thumbs[style + '/' + file];
        if (thumbs['styles/' + style + '/' + file]) return thumbs['styles/' + style + '/' + file];
        if (thumbs[file]) return thumbs[file];
      }
      return 'styles/' + style + '/' + file;
    }

    function broadcastVariant(style, variantIdx) {
      var list = getVariantsForStyle(style);
      if (!list.length) return;
      var safeIdx = Math.max(0, Math.min(list.length - 1, variantIdx));
      var info = list[safeIdx];

      var msg = {
        type: 'SET_STYLE_VARIANT',
        style: style,
        variant: safeIdx,
        label: info.label,
        file: info.file,
        formation: info.formation || 'wave'
      };

      document.querySelectorAll('iframe').forEach(function (frame) {
        if (frame && frame.contentWindow) {
          try {
            frame.contentWindow.postMessage(msg, '*');
          } catch (_e) {}
        }
      });

      try {
        global.dispatchEvent(new CustomEvent('jig-style-variant', { detail: msg }));
      } catch (_e) {}
    }

    function showTooltipForNotch(btn, idx) {
      var list = getVariantsForStyle(activeStyle);
      if (!tooltipEl || !list.length || idx < 0 || idx >= list.length) return;
      var info = list[idx];
      var caption = idx + 1 + '/' + list.length + ' \u00b7 ' + info.label;
      if (tooltipLblEl) tooltipLblEl.textContent = caption;
      if (tooltipImgEl) {
        var src = resolveThumbSrc(activeStyle, info.file);
        tooltipImgEl.setAttribute('src', src);
      }
      if (btn) {
        var centerY = btn.offsetTop + btn.offsetHeight / 2;
        tooltipEl.style.top = centerY + 'px';
      }
      tooltipEl.classList.add('visible');
    }

    function hideTooltip() {
      if (tooltipEl) tooltipEl.classList.remove('visible');
    }

    function syncNotchActiveClasses() {
      if (!trackEl) return;
      var buttons = trackEl.querySelectorAll('.rvn-notch');
      for (var i = 0; i < buttons.length; i++) {
        var isCurrent = i === activeVariant;
        buttons[i].classList.toggle('active', isCurrent);
        buttons[i].setAttribute('aria-pressed', isCurrent ? 'true' : 'false');
      }
    }

    function selectVariant(idx, forceBroadcast) {
      activeStyle = getBodyStyle();
      if (renderedStyle !== activeStyle) {
        renderNotchesForStyle(activeStyle);
      }
      var list = getVariantsForStyle(activeStyle);
      if (!list.length) return;
      var nextIdx = Math.max(0, Math.min(list.length - 1, idx));
      var changed = nextIdx !== activeVariant;
      activeVariant = nextIdx;
      document.body.setAttribute('data-style-variant', String(activeVariant));
      document.documentElement.setAttribute('data-style-variant', String(activeVariant));
      syncNotchActiveClasses();
      if (changed || forceBroadcast) {
        broadcastVariant(activeStyle, activeVariant);
      }
    }

    function renderNotchesForStyle(style) {
      if (!trackEl) return;
      renderedStyle = style;
      trackEl.innerHTML = '';
      hideTooltip();

      var list = getVariantsForStyle(style);
      if (!list.length || style === 'clone') {
        nav.classList.add('is-hidden');
        return;
      }

      list.forEach(function (item, idx) {
        var btn = document.createElement('button');
        btn.type = 'button';
        btn.className = 'rvn-notch' + (idx === activeVariant ? ' active' : '');
        btn.setAttribute('data-variant-idx', String(idx));
        btn.setAttribute('aria-label', idx + 1 + '/' + list.length + ' \u00b7 ' + item.label);
        btn.setAttribute('aria-pressed', idx === activeVariant ? 'true' : 'false');

        var thumb = document.createElement('img');
        thumb.className = 'rvn-thumb';
        thumb.alt = '';
        thumb.draggable = false;
        thumb.setAttribute('src', resolveThumbSrc(style, item.file));
        thumb.addEventListener('error', function () {
          thumb.style.display = 'none';
          var fallback = document.createElement('span');
          fallback.className = 'rvn-swatch-fallback';
          fallback.textContent = String(idx + 1);
          btn.appendChild(fallback);
        });
        btn.appendChild(thumb);

        btn.addEventListener('pointerenter', function () {
          showTooltipForNotch(btn, idx);
        });
        btn.addEventListener('focus', function () {
          showTooltipForNotch(btn, idx);
        });
        btn.addEventListener('click', function (e) {
          e.stopPropagation();
          selectVariant(idx, true);
          showTooltipForNotch(btn, idx);
        });

        trackEl.appendChild(btn);
      });
    }

    function syncVisibility() {
      var curStyle = getBodyStyle();
      var list = getVariantsForStyle(curStyle);
      var shouldShow = curStyle !== 'clone' && list.length > 0;
      if (curStyle !== activeStyle) {
        activeStyle = curStyle;
        activeVariant = 0;
        document.body.setAttribute('data-style-variant', '0');
        renderNotchesForStyle(activeStyle);
        if (shouldShow) broadcastVariant(activeStyle, 0);
      } else if (renderedStyle !== activeStyle && shouldShow) {
        renderNotchesForStyle(activeStyle);
      }
      nav.classList.toggle('is-hidden', !shouldShow);
    }

    nav.addEventListener('pointerleave', hideTooltip);
    syncVisibility();

    if (typeof MutationObserver !== 'undefined') {
      var obs = new MutationObserver(syncVisibility);
      obs.observe(document.body, {
        attributes: true,
        attributeFilter: ['class', 'data-jig', 'data-style', 'data-variant-notches-visible']
      });
    }

    return {
      selectVariant: selectVariant,
      syncVisibility: syncVisibility
    };
  }

  if (typeof document !== 'undefined') {
    if (document.readyState === 'loading') {
      document.addEventListener('DOMContentLoaded', mountVariantNotches);
    } else {
      mountVariantNotches();
    }
  }

  if (global.JigAgent) {
    global.JigAgent.mountVariantNotches = mountVariantNotches;
  }
})(typeof window !== 'undefined' ? window : globalThis);
